<div class="summary-wrapper">
    <div class="summary-header" id="panelTrigger">
        <div class="header-title-group">
            <span class="header-icon">✧</span>
            场景概览
        </div>
        <div class="meta-badges" id="metaContainer"></div>
    </div>

    <div class="collapse-viewport" id="viewportArea">
        <div id="statusGrid" class="status-grid"></div>
        <ul class="content-stream" id="streamList"></ul>
    </div>
</div>

<template id="payload1">$1</template>
<template id="payload2">$2</template>

<script>
(function() {
    'use strict';

    class SceneSummaryModule {
        constructor() {
            this.domRefs = {
                payload1: document.getElementById('payload1'),
                payload2: document.getElementById('payload2'),
                metaContainer: document.getElementById('metaContainer'),
                statusGrid: document.getElementById('statusGrid'),
                listContainer: document.getElementById('streamList'),
                triggerHeader: document.getElementById('panelTrigger'),
                viewport: document.getElementById('viewportArea')
            };
            this.init();
        }

        init() {
            this.renderContent();
            this.bindEvents();
        }

        parseData() {
            const raw1 = this.domRefs.payload1 ? (this.domRefs.payload1.innerHTML || "") : "";
            const raw2 = this.domRefs.payload2 ? (this.domRefs.payload2.innerHTML || "") : "";
            const combinedRaw = raw1 + '\n' + raw2;

            const lines = combinedRaw.split('\n').map(line => line.trim()).filter(Boolean);

            const metaItems = [];
            const attrItems = [];
            const streamItems = [];

            lines.forEach(line => {
                const colonIndex = Math.max(line.indexOf('：'), line.indexOf(':'));
                let tag = '记录';
                let text = line;

                if (colonIndex > 0 && colonIndex <= 15) {
                    tag = line.substring(0, colonIndex).trim();
                    text = line.substring(colonIndex + 1).trim();
                }

                tag = tag.replace(/[【】\[\]]/g, '').trim();

                if (['地点', '梦历', '梦纪', '昆仑历', '时间', '日期'].includes(tag)) {
                    metaItems.push({ tag, text });
                } else if (['人物', '位置', '姿势', '状态'].includes(tag)) {
                    attrItems.push({ tag, text });
                } else {
                    streamItems.push({ tag, text });
                }
            });

            return { metaItems, attrItems, streamItems };
        }

        getIconForTag(tag) {
            if (tag === '地点' || tag === '位置') return '📍';
            if (tag === '梦历' || tag === '梦纪' || tag === '昆仑历' || tag === '时间' || tag === '日期') return '🕰️';
            if (tag === '人物') return '👥';
            if (tag === '姿势' || tag === '状态') return '🧍';
            return '✨';
        }

        renderContent() {
            const { metaItems, attrItems, streamItems } = this.parseData();

            if (metaItems.length > 0 && this.domRefs.metaContainer) {
                this.domRefs.metaContainer.innerHTML = metaItems.map(item => `
                    <span class="meta-pill">
                        <i style="font-style:normal">${this.getIconForTag(item.tag)}</i>
                        ${item.text}
                    </span>
                `).join('');
            }

            if (attrItems.length > 0 && this.domRefs.statusGrid) {
                this.domRefs.statusGrid.innerHTML = attrItems.map(item => `
                    <div class="status-item">
                        <div class="status-label">
                            <i style="font-style:normal">${this.getIconForTag(item.tag)}</i> ${item.tag}
                        </div>
                        <div class="status-value">${item.text}</div>
                    </div>
                `).join('');
            }

            if (streamItems.length > 0 && this.domRefs.listContainer) {
                this.domRefs.listContainer.innerHTML = streamItems.map(item => `
                    <li class="stream-card">
                        <div class="card-tag">${item.tag}</div>
                        <div class="card-desc">${item.text}</div>
                    </li>
                `).join('');
            }
        }

        bindEvents() {
            if (this.domRefs.triggerHeader && this.domRefs.viewport) {
                this.domRefs.triggerHeader.addEventListener('click', () => {
                    this.domRefs.viewport.classList.toggle('is-folded');
                });
            }
        }
    }

    try {
        new SceneSummaryModule();
    } catch (e) {
        console.error("面板初始化失败:", e);
    }
})();
</script>
</body>
</html>

