        // 4. 将提取到的多模态图片/文件附件转移挂载至构建的 【ToolCall引导】 user 节点中（原消息彻底剥离）
        if (Array.isArray(body['images']) && body['images'].length > 0) {
            for (const img of body['images']) {
                if (typeof img === 'string' && img.startsWith('data:image/')) {
                    collectedAttachments.push({
                        type: 'image_url',
                        image_url: { url: img, detail: 'low' }
                    });
                } else if (isMultimodalContentPart(img)) {
                    collectedAttachments.push(JSON.parse(JSON.stringify(img)));
                }
            }
        }

        if (collectedAttachments.length > 0) {
            // 优先定位 [UserProjectTrigger] (条目 17: 用户项目指令) 节点，次优定位首个 user 节点，兜底为末尾 user 节点
            let targetUserMsg = harmlessMessages.find(m => m.role === 'user' && typeof m.content === 'string' && (m.content.includes('[UserProjectTrigger]') || m.content.includes('USER_OPERATOR')));
            if (!targetUserMsg) {
                targetUserMsg = harmlessMessages.find(m => m.role === 'user');
            }
            if (!targetUserMsg && harmlessMessages.length > 0) {
                targetUserMsg = harmlessMessages[harmlessMessages.length - 1];
            }

            if (targetUserMsg) {
                const textContent = typeof targetUserMsg.content === 'string'
                    ? targetUserMsg.content
                    : (Array.isArray(targetUserMsg.content)
                        ? targetUserMsg.content.filter(p => p && (p.type === 'text' || typeof p.text === 'string')).map(p => p.text || '').join('\n')
                        : '');

                targetUserMsg.content = [
