                const tx = (maxX - p0x) / vx;
                if (tx >= 0 && tx < minT) {
                    minT = tx; hitType = 'wall'; normX = -1; normY = 0;
                }
            } else if (vx < -0.0001) {
                const tx = (minX - p0x) / vx;
                if (tx >= 0 && tx < minT) {
                    minT = tx; hitType = 'wall'; normX = 1; normY = 0;
                }
            }

            if (vy > 0.0001) {
                const ty = (maxY - p0y) / vy;
                if (ty >= 0 && ty < minT) {
                    minT = ty; hitType = 'wall'; normX = 0; normY = -1;
                }
            } else if (vy < -0.0001) {
                const ty = (minY - p0y) / vy;
                if (ty >= 0 && ty < minT) {
                    minT = ty; hitType = 'wall'; normX = 0; normY = 1;
                }
            }

            // 3. 图标/头像目标求交（排除刚碰撞过的 ignoreTarget，防止紧密接触面的重复触发）
            const invVx = Math.abs(vx) > 0.0001 ? 1 / vx : 0;
            const invVy = Math.abs(vy) > 0.0001 ? 1 / vy : 0;
            const signVx = vx >= 0 ? 1 : -1;
            const signVy = vy >= 0 ? 1 : -1;

            const targetLen = iconTargets.length;
            for (let i = 0; i < targetLen; i++) {
                const item = iconTargets[i];
                if (item === ignoreTarget) continue;
                const rect = item.rect;

                const ibLeft = rect.left - ballRadius;
                const ibRight = rect.right + ballRadius;
                const ibTop = rect.top - ballRadius;
                const ibBottom = rect.bottom + ballRadius;

                let tNear = -Infinity;
                let tFar = Infinity;
                let slabNormX = 0;
                let slabNormY = 0;

                if (invVx !== 0) {
                    let t1 = (ibLeft - p0x) * invVx;
                    let t2 = (ibRight - p0x) * invVx;
                    let nx = -signVx;
                    if (t1 > t2) { const tmp = t1; t1 = t2; t2 = tmp; nx = -nx; }
                    if (t1 > tNear) { tNear = t1; slabNormX = nx; slabNormY = 0; }
                    if (t2 < tFar) tFar = t2;
                } else if (p0x < ibLeft || p0x > ibRight) {
                    continue;
                }

                if (invVy !== 0) {
                    let t1 = (ibTop - p0y) * invVy;
                    let t2 = (ibBottom - p0y) * invVy;
                    let ny = -signVy;
                    if (t1 > t2) { const tmp = t1; t1 = t2; t2 = tmp; ny = -ny; }
                    if (t1 > tNear) { tNear = t1; slabNormX = 0; slabNormY = ny; }
                    if (t2 < tFar) tFar = t2;
                } else if (p0y < ibTop || p0y > ibBottom) {
                    continue;
                }

                if (tNear <= tFar && tNear > 0.001 && tNear < minT) {
                    minT = tNear;
                    hitType = 'icon';
                    hitTarget = item;
                    normX = slabNormX;
                    normY = slabNormY;
                }
            }

            // 4. 极端兜底处理：若仍未找到正向碰撞面，使用小步安全推进并反向，防止死锁
            if (minT === Infinity || minT < 0) {
                minT = 2;
                normX = -(vx ? signVx : 1);
                normY = -(vy ? signVy : 1);
            }

            const dot = vx * normX + vy * normY;
            const nextVx = vx - 2 * dot * normX;
            const nextVy = vy - 2 * dot * normY;

            const p1x = Math.max(minX, Math.min(maxX, p0x + vx * minT));
            const p1y = Math.max(minY, Math.min(maxY, p0y + vy * minT));
            const dx = p1x - p0x;
            const dy = p1y - p0y;
            const length = Math.hypot(dx, dy);
            const speed = Math.hypot(vx, vy) || 1;

            const seg = this._acquireSegment();
            seg.p0.x = p0x;
            seg.p0.y = p0y;
            seg.p1.x = p1x;
            seg.p1.y = p1y;
            seg.vx = vx;
            seg.vy = vy;
            seg.nextVel.x = nextVx;
            seg.nextVel.y = nextVy;
            seg.length = length;
            seg.durationMs = Math.max(8, (length / speed) * 16.6); // 保证最小持续时长，防止段极短导致微频切段
            seg.hitType = hitType;
            seg.hitTarget = hitTarget;
            seg.normal.x = normX;
            seg.normal.y = normY;

            return seg;
        }

        planSegments(startPos, startVx, startVy, count, iconTargets, initialIgnoreTarget = null, initialNormX = 0, initialNormY = 0) {
            this.resetPool();
            let curX = startPos.x;
            let curY = startPos.y;
            let curVx = startVx;
            let curVy = startVy;
            let lastTarget = initialIgnoreTarget;
            let lastNormX = initialNormX;
            let lastNormY = initialNormY;

            for (let i = 0; i < count; i++) {
                const seg = this.castRay(curX, curY, curVx, curVy, BALL_RADIUS, iconTargets, lastTarget, lastNormX, lastNormY);
                this._plannedResult.push(seg);
                curX = seg.p1.x;
                curY = seg.p1.y;
                curVx = seg.nextVel.x;
                curVy = seg.nextVel.y;
                lastTarget = seg.hitType === 'icon' ? seg.hitTarget : null;
                lastNormX = seg.normal.x;
                lastNormY = seg.normal.y;
            }

            return this._plannedResult;
        }
    }

    // ==========================================
    // 4. 弹弓渲染与按需交互控制器 (Slingshot Controller)
    // ==========================================
    class SlingshotRenderer {
        constructor(win, doc, boundaryMgr) {
            this.win = win;
            this.doc = doc;
            this.bm = boundaryMgr;

            this.state = 'IDLE';
            this.ball = { x: 0, y: 0, vx: 0, vy: 0, radius: BALL_RADIUS };
            this.forkLeft = { x: 0, y: 0 };
            this.forkRight = { x: 0, y: 0 };
            this.forkBase = { x: 0, y: 0 };
            this.slingCenter = { x: 0, y: 0 };

            this.activePointerId = null;
            this.canvas = null;
            this.ctx = null;
            this.handleEl = null;
            this.dpr = win.devicePixelRatio || 1;
            this.logicalWidth = win.innerWidth;
            this.logicalHeight = win.innerHeight;

            this.initCanvas();
            this.initHandle();
            this.bindEvents();
            this.resetBallToSling();
        }

        initCanvas() {
            this.canvas = this.doc.createElement('canvas');
            this.canvas.id = '__slingshot_game_canvas__';
            this.canvas.style.cssText = 'position:fixed;left:0;top:0;width:100vw;height:100vh;z-index:999997;pointer-events:none;touch-action:none;';

            // 开启 desynchronized 绕过合成器队列，实现最低延迟直通渲染
            this.ctx = this.canvas.getContext('2d', { alpha: true, desynchronized: true }) || this.canvas.getContext('2d');
            this.doc.body.appendChild(this.canvas);
            this.resize();
        }

        initHandle() {
            this.handleEl = this.doc.createElement('div');
            this.handleEl.id = '__slingshot_handle__';
            this.handleEl.style.cssText = 'position:fixed;left:0;top:0;width:70px;height:70px;border-radius:50%;z-index:999999;cursor:grab;touch-action:none;pointer-events:auto;background:transparent;will-change:transform;';
            this.handleEl.title = '按住拉动弹弓发射小球';
            this.doc.body.appendChild(this.handleEl);
        }

        // 使用 GPU transform: translate3d 替代 left/top 修改，彻底杜绝拖拽时的样式重排 (Reflow)
        updateHandlePosition() {
            if (!this.handleEl) return;
            if (this.state === 'FLYING') {
                this.handleEl.style.display = 'none';
            } else {
                this.handleEl.style.display = 'block';
                const tx = Math.round(this.ball.x - 35);
                const ty = Math.round(this.ball.y - 35);
                this.handleEl.style.transform = `translate3d(${tx}px, ${ty}px, 0)`;
            }
        }

        resize() {
            if (!this.canvas) return;
            this.dpr = Math.min(this.win.devicePixelRatio || 1, 2); // 限制最高 2x 超采样，大幅降低 4K 屏填充压力
            this.logicalWidth = this.win.innerWidth;
            this.logicalHeight = this.win.innerHeight;
            this.canvas.width = Math.floor(this.logicalWidth * this.dpr);
            this.canvas.height = Math.floor(this.logicalHeight * this.dpr);
            this.ctx.setTransform(this.dpr, 0, 0, this.dpr, 0, 0);

            this.bm.update();
            this.updateSlingGeometry();
            if (this.state === 'IDLE') {
                this.resetBallToSling();
            } else {
                this.updateHandlePosition();
            }
        }

        updateSlingGeometry() {
            const anchor = this.bm.anchor;
            this.forkBase.x = anchor.x;
            this.forkBase.y = anchor.y;
            this.forkLeft.x = anchor.x - 22;
            this.forkLeft.y = anchor.y - 36;
            this.forkRight.x = anchor.x + 22;
            this.forkRight.y = anchor.y - 36;
            this.slingCenter.x = anchor.x;
            this.slingCenter.y = anchor.y - 36;
        }

        resetBallToSling() {
            this.updateSlingGeometry();
            this.state = 'IDLE';
            this.ball.x = this.forkBase.x;
            this.ball.y = this.forkBase.y - 32;
            this.ball.vx = 0;
            this.ball.vy = 0;
            this.updateHandlePosition();
        }

        bindEvents() {
            this.onPointerDown = this.handlePointerDown.bind(this);
            this.onPointerMove = this.handlePointerMove.bind(this);
            this.onPointerUp = this.handlePointerUp.bind(this);

            // 平时仅在 handleEl 上监听 pointerdown，window 保持 0 监听器！
            this.handleEl.addEventListener('pointerdown', this.onPointerDown);

            let resizeRaf = null;
            this.onResize = () => {
                this.bm.markDirty();
                if (this.onInvalidateTargets) this.onInvalidateTargets();
                if (resizeRaf) return;
                resizeRaf = this.win.requestAnimationFrame(() => {
                    resizeRaf = null;
                    this.resize();
                    if (this.onRequestRender) this.onRequestRender();
                });
            };

            let scrollRaf = null;
            this.onScroll = () => {
                // 第一层：高频纳秒级标脏（零 DOM 读取，不产生 GC）
                this.bm.markDirty();
                if (this.onInvalidateTargets) this.onInvalidateTargets();
                if (scrollRaf) return;
                // 第二层：屏幕刷新率级节流（rAF 合并更新几何与弹弓底座）
                scrollRaf = this.win.requestAnimationFrame(() => {
                    scrollRaf = null;
                    this.bm.update();
                    this.updateSlingGeometry();
                    if (this.state === 'IDLE') {
                        this.resetBallToSling();
                    } else {
                        this.updateHandlePosition();
                    }
                    if (this.onRequestRender) this.onRequestRender();
                });
            };

            this.onWheel = () => {
                this.bm.markDirty();
                if (this.onInvalidateTargets) this.onInvalidateTargets();
            };

            this.win.addEventListener('resize', this.onResize, { passive: true });
            // 使用 capture: true 穿透捕获所有层级子容器（#chat, #sheld, 自定义滚动条等）的滚动
            this.win.addEventListener('scroll', this.onScroll, { passive: true, capture: true });
            this.win.addEventListener('wheel', this.onWheel, { passive: true, capture: true });
        }

        _detachDragListeners() {
            this.win.removeEventListener('pointermove', this.onPointerMove);
            this.win.removeEventListener('pointerup', this.onPointerUp);
            this.win.removeEventListener('pointercancel', this.onPointerUp);
        }

        handlePointerDown(e) {
            this.state = 'DRAGGING';
            this.activePointerId = e.pointerId;
            if (this.handleEl.setPointerCapture) {
                try { this.handleEl.setPointerCapture(e.pointerId); } catch (_) { }
            }
            this.handleEl.style.cursor = 'grabbing';

            // 按需挂载移动与释放监听
            this.win.addEventListener('pointermove', this.onPointerMove, { passive: false });
            this.win.addEventListener('pointerup', this.onPointerUp, { passive: false });
            this.win.addEventListener('pointercancel', this.onPointerUp, { passive: false });

            if (this.onWake) this.onWake();
            if (this.onDragStart) this.onDragStart();
            e.preventDefault();
            e.stopPropagation();
        }

        handlePointerMove(e) {
            if (this.state !== 'DRAGGING' || e.pointerId !== this.activePointerId) return;

            let dx = e.clientX - this.slingCenter.x;
            let dy = e.clientY - this.slingCenter.y;
            const distSq = dx * dx + dy * dy;

            if (distSq > MAX_PULL_DISTANCE * MAX_PULL_DISTANCE) {
                const scale = MAX_PULL_DISTANCE / Math.sqrt(distSq);
                dx *= scale;
                dy *= scale;
            }

            this.ball.x = this.slingCenter.x + dx;
            this.ball.y = this.slingCenter.y + dy;
            this.updateHandlePosition();

            if (this.onWake) this.onWake();
            e.preventDefault();
        }

        handlePointerUp(e) {
            if (this.state !== 'DRAGGING' || e.pointerId !== this.activePointerId) return;

            this._detachDragListeners();

            const pullDx = this.ball.x - this.slingCenter.x;
            const pullDy = this.ball.y - this.slingCenter.y;
            const pullDistSq = pullDx * pullDx + pullDy * pullDy;

            if (pullDistSq > 144) { // 12^2
                this.state = 'FLYING';
                this.ball.vx = -pullDx * PULL_FORCE_SCALE;
                this.ball.vy = -pullDy * PULL_FORCE_SCALE;
            } else {
                this.resetBallToSling();
            }

            this.activePointerId = null;
            if (this.handleEl.releasePointerCapture) {
                try { this.handleEl.releasePointerCapture(e.pointerId); } catch (_) { }
            }
            this.handleEl.style.cursor = 'grab';
            this.updateHandlePosition();
            if (this.onWake) this.onWake();
            if (this.onRequestRender) this.onRequestRender();
            e.preventDefault();
        }

        drawTrajectory(ctx) {
            if (this.state !== 'DRAGGING') return;

            const pullDx = this.ball.x - this.slingCenter.x;
            const pullDy = this.ball.y - this.slingCenter.y;
            if (pullDx * pullDx + pullDy * pullDy < 100) return;

            const stepX = -pullDx * PULL_FORCE_SCALE * 1.2;
            const stepY = -pullDy * PULL_FORCE_SCALE * 1.2;

            let curX = this.ball.x;
            let curY = this.ball.y;

            for (let i = 0; i < TRAJECTORY_STEPS; i++) {
                curX += stepX;
                curY += stepY;
                const item = TRAJECTORY_LUT[i];
                ctx.beginPath();
                ctx.arc(curX, curY, item.radius, 0, TAU);
                ctx.fillStyle = item.color;
                ctx.fill();
            }
        }

        drawSlingshot(ctx) {
            this.updateSlingGeometry();
            const scx = this.slingCenter.x;
            const scy = this.slingCenter.y;

            ctx.lineCap = 'round';
            ctx.lineJoin = 'round';

            // 1. 主干支柱
            ctx.strokeStyle = '#6d4c41';
            ctx.lineWidth = 7;
            ctx.beginPath();
            ctx.moveTo(this.forkBase.x, this.forkBase.y);
            ctx.lineTo(scx, scy + 10);
            ctx.stroke();

            const isHolding = this.state === 'IDLE' || this.state === 'DRAGGING';

            // 2. 后皮筋
            if (isHolding) {
                ctx.strokeStyle = '#4e342e';
                ctx.lineWidth = 5;
                ctx.beginPath();
                ctx.moveTo(this.forkLeft.x, this.forkLeft.y);
                ctx.lineTo(this.ball.x, this.ball.y);
                ctx.stroke();
            }

            // 3. 左右分叉
            ctx.strokeStyle = '#8d6e63';
            ctx.lineWidth = 6;
            ctx.beginPath();
            ctx.moveTo(scx, scy + 10);
            ctx.lineTo(this.forkLeft.x, this.forkLeft.y);
            ctx.moveTo(scx, scy + 10);
            ctx.lineTo(this.forkRight.x, this.forkRight.y);
            ctx.stroke();

            // 4. 前皮筋与皮兜
            if (isHolding) {
                ctx.strokeStyle = '#3e2723';
                ctx.lineWidth = 5;
                ctx.beginPath();
                ctx.moveTo(this.forkRight.x, this.forkRight.y);
                ctx.lineTo(this.ball.x, this.ball.y);
                ctx.stroke();

                ctx.fillStyle = '#212121';
                ctx.beginPath();
                ctx.arc(this.ball.x, this.ball.y, this.ball.radius * 0.7, 0, TAU);
                ctx.fill();

                this.drawTrajectory(ctx);
            }
        }

        drawBall(ctx) {
            ctx.beginPath();
            ctx.arc(this.ball.x, this.ball.y, this.ball.radius, 0, TAU);
            ctx.fillStyle = '#ff2d55';
            ctx.fill();
        }

        destroy() {
            this._detachDragListeners();
            if (this.handleEl) {
                this.handleEl.removeEventListener('pointerdown', this.onPointerDown);
                this.handleEl.remove();
                this.handleEl = null;
            }
            if (this.canvas) {
                this.canvas.remove();
                this.canvas = null;
            }
            this.win.removeEventListener('resize', this.onResize);
            this.win.removeEventListener('scroll', this.onScroll, { capture: true });
            this.win.removeEventListener('wheel', this.onWheel, { capture: true });
        }
    }

    // ==========================================
    // 5. 粒子特效系统 (Zero-GC Swap-and-Pop Pool)
    // ==========================================
    class ParticleManager {
        constructor() {
            this.particles = [];
            this._pool = [];
            this.maxParticles = 64;
            for (let i = 0; i < this.maxParticles; i++) {
                this._pool.push({ x: 0, y: 0, vx: 0, vy: 0, radius: 0, alpha: 1, decay: 0.04, color: '#ffeb3b' });
            }
        }

        emitSparks(x, y, normalX, normalY, count = 6, color = '#ffeb3b') {
            const actualCount = Math.min(count, this.maxParticles - this.particles.length);
            if (actualCount <= 0) return;

            const baseAngle = Math.atan2(normalY, normalX);
            for (let i = 0; i < actualCount; i++) {
                const angle = baseAngle + (Math.random() - 0.5) * 1.5;
                const speed = 2.5 + Math.random() * 6.0;

                const p = this._pool.pop() || { x: 0, y: 0, vx: 0, vy: 0, radius: 0, alpha: 1, decay: 0.04, color: '' };
                p.x = x;
                p.y = y;
                p.vx = Math.cos(angle) * speed;
                p.vy = Math.sin(angle) * speed;
                p.radius = 2 + Math.random() * 2.5;
                p.alpha = 1;
                p.decay = 0.035 + Math.random() * 0.04;
                p.color = color;

                this.particles.push(p);
            }
        }

        updateAndDraw(ctx) {
            const len = this.particles.length;
            if (len === 0) return;

            for (let i = len - 1; i >= 0; i--) {
                const p = this.particles[i];
                p.x += p.vx;
                p.y += p.vy;
                p.vx *= 0.96;
                p.vy *= 0.96;
                p.alpha -= p.decay;

                if (p.alpha <= 0) {
                    this._pool.push(p);
                    const last = this.particles.pop();
                    if (i < this.particles.length) this.particles[i] = last;
                    continue;
                }

                ctx.beginPath();
                ctx.arc(p.x, p.y, p.radius * p.alpha, 0, TAU);
                ctx.fillStyle = p.color;
                ctx.globalAlpha = p.alpha;
                ctx.fill();
            }
            ctx.globalAlpha = 1;
        }
    }

    // ==========================================
    // 6. 零重排空间索引文字扫掠系统 (Zero-Reflow Text Sweep Engine)
    // ==========================================
    class TextSweepEngine {
        constructor(win, doc, boundaryMgr) {
            this.win = win;
            this.doc = doc;
            this.bm = boundaryMgr;

            this.bakedContainers = new Map(); // container -> { spans: Array<HTMLElement>, localX: Float32Array, localY: Float32Array, count: number }
            this.wrappedOriginals = new Map(); // container -> originalHTML
            this.visibleContainers = []; // 缓存当前可视区内的消息容器 Rect
            this.containersDirty = true;

            // 预分配时间轴事件池（杜绝每次切段产生新对象）
            this._eventPool = [];
            this.currentTimeline = [];
            this.timelineIndex = 0;

            // 活跃抖动元素回收队列（字符与容器共用，无闭包内存开销）
            this.activeShakes = [];

            // 异步后台空闲烘焙队列（使用 Set 保证 O(1) 去重，严格杜绝对象匹配缺陷）
            this._idleBakeSet = new Set();
            this._idleBakeQueue = [];
            this._isIdleBaking = false;
            this.MAX_ACTIVE_BAKED = 10; // LRU 活跃烘焙容器上限，严格封顶 DOM 节点总数

            this.injectStyles();
        }

        injectStyles() {
            const styleId = '__sl_shake_anim_style__';
            if (this.doc.getElementById(styleId)) return;
            const style = this.doc.createElement('style');
            style.id = styleId;
            style.textContent = `
                @keyframes sl-pure-shake {
                    0% { transform: translate3d(0, 0, 0) rotate(0deg); }
                    25% { transform: translate3d(0, -2px, 0) rotate(4deg); }
                    60% { transform: translate3d(0, 1.2px, 0) rotate(-2.5deg); }
                    100% { transform: translate3d(0, 0, 0) rotate(0deg); }
                }
                .sl-char {
                    display: inline-block;
                    transform-origin: center bottom;
                }
                .sl-shake {
                    animation: sl-pure-shake 0.18s ease-out both !important;
                }
                @keyframes sl-mes-shake {
                    0% { transform: translate3d(0, 0, 0); }
                    25% { transform: translate3d(-1px, 1.5px, 0); }
                    50% { transform: translate3d(1px, -1px, 0); }
                    100% { transform: translate3d(0, 0, 0); }
                }
                .sl-mes-hit {
                    animation: sl-mes-shake 0.22s ease-out both !important;
                }
                @keyframes sl-icon-jelly {
                    0% { transform: translate3d(0, 0, 0) scale(1) rotate(0deg); }
                    20% { transform: translate3d(var(--sl-px, 0px), var(--sl-py, 0px), 0) scale(1.28) rotate(var(--sl-rot, 0deg)); }
                    60% { transform: translate3d(0, 0, 0) scale(0.94) rotate(0deg); }
                    100% { transform: translate3d(0, 0, 0) scale(1) rotate(0deg); }
                }
                .sl-icon-hit {
                    animation: sl-icon-jelly 0.48s cubic-bezier(0.175, 0.885, 0.32, 1.35) both !important;
                }
            `;
            this.doc.head.appendChild(style);
        }

        invalidateCache() {
            this.containersDirty = true;
        }

        _updateVisibleContainers() {
            if (!this.containersDirty) return;
            this.visibleContainers.length = 0;

            const root = this.bm.chatEl || this.doc.getElementById('chat') || this.doc.getElementById('sheld') || this.doc;
            const list = root.querySelectorAll('.mes_text');
            const vh = this.win.innerHeight || 800;
            // 上下增加 100px 缓冲带，确保滚动边缘的文字预先进入计算范围
            const minBufferY = -100;
            const maxBufferY = vh + 100;

            for (let i = 0, len = list.length; i < len; i++) {
                const c = list[i];
                if (!c.isConnected) continue;
                const r = c.getBoundingClientRect();
                if (r.width > 0 && r.height > 0 && r.bottom >= minBufferY && r.top <= maxBufferY) {
                    this.visibleContainers.push({
                        el: c,
                        left: r.left,
                        top: r.top,
                        right: r.right,
                        bottom: r.bottom
                    });
                }
            }
            this.containersDirty = false;
        }

        // 异步空闲批量烘焙：使用 Set 严密去重并安全调度
        requestIdleBake(container, containerRect) {
            if (!container || !container.isConnected) return;
            if (this.bakedContainers.has(container)) return;

            if (!this._idleBakeSet.has(container)) {
                this._idleBakeSet.add(container);
                this._idleBakeQueue.push({ el: container, rect: containerRect });
            }

            if (this._isIdleBaking) return;
            this._processNextIdleBake();
        }

        _processNextIdleBake() {
            if (this._idleBakeQueue.length === 0) {
                this._isIdleBaking = false;
                return;
            }
            this._isIdleBaking = true;

            const scheduleNext = this.win.requestIdleCallback || ((cb) => setTimeout(cb, 16));
            scheduleNext(() => {
                const item = this._idleBakeQueue.shift();
                if (item) {
                    this._idleBakeSet.delete(item.el);
                    if (item.el && item.el.isConnected) {
                        this.bakeContainer(item.el, item.rect);
                    }
                }
                if (this._idleBakeQueue.length > 0) {
                    this._processNextIdleBake();
                } else {
                    this._isIdleBaking = false;
                }
            });
        }

        // 烘焙单个容器：带 DOM 活性校验与 LRU 容量回收，杜绝节点溢出
        bakeContainer(container, containerRect) {
            if (!container || !container.isConnected) return null;

            let record = this.bakedContainers.get(container);
            if (record) {
                // 活性校验：如果容器内的 span 已经断连（被酒馆原生打字/重绘覆盖），则清理旧缓存重新烘焙
                if (record.spans.length > 0 && record.spans[0].isConnected) {
                    return record;
                }
                this.bakedContainers.delete(container);
                this.wrappedOriginals.delete(container);
            }

            // LRU 保护：限制全局活跃已烘焙容器总数，超出时将最早的容器还原回原生文本
            if (this.bakedContainers.size >= this.MAX_ACTIVE_BAKED) {
                const oldest = this.bakedContainers.keys().next().value;
                if (oldest) {
                    const orig = this.wrappedOriginals.get(oldest);
                    if (orig && oldest.isConnected) {
                        try { oldest.innerHTML = orig; } catch (_) { }
                    }
                    this.wrappedOriginals.delete(oldest);
                    this.bakedContainers.delete(oldest);
                }
            }

            // 兜底矩形获取
            const rect = containerRect || container.getBoundingClientRect();
            if (rect.width <= 0 || rect.height <= 0) return null;

            this.wrappedOriginals.set(container, container.innerHTML);

            const textNodes = [];
            const walker = this.doc.createTreeWalker(
                container,
                NodeFilter.SHOW_TEXT,
                {
                    acceptNode: (n) => {
                        if (!n.nodeValue || !n.nodeValue.trim()) return NodeFilter.FILTER_REJECT;
                        if (n.parentElement && n.parentElement.classList.contains('sl-char')) return NodeFilter.FILTER_REJECT;
                        return NodeFilter.FILTER_ACCEPT;
                    }
                }
            );

            while (walker.nextNode()) textNodes.push(walker.currentNode);

            const createdSpans = [];
            let totalChars = 0;
            const MAX_CHARS_PER_MES = 3500; // 扩充至 3500 字符，全量覆盖整篇小说级长回复，杜绝长文滚动断层

            for (let j = 0, tLen = textNodes.length; j < tLen; j++) {
                if (totalChars >= MAX_CHARS_PER_MES) break;
                const textNode = textNodes[j];
                const parent = textNode.parentNode;
                if (!parent) continue;

                const text = textNode.nodeValue;
                const frag = this.doc.createDocumentFragment();

                for (let k = 0, sLen = text.length; k < sLen; k++) {
                    const ch = text[k];
                    if (ch === ' ' || ch === '\t' || ch === '\n' || ch === '\r') {
                        frag.appendChild(this.doc.createTextNode(ch));
                    } else if (totalChars < MAX_CHARS_PER_MES) {
                        const span = this.doc.createElement('span');
                        span.className = 'sl-char';
                        span.textContent = ch;
                        frag.appendChild(span);
                        createdSpans.push(span);
                        totalChars++;
                    } else {
                        frag.appendChild(this.doc.createTextNode(ch));
                    }
                }
                parent.replaceChild(frag, textNode);
            }

            const count = createdSpans.length;
            const localX = new Float32Array(count);
            const localY = new Float32Array(count);
            const liveRect = container.getBoundingClientRect();
            const cLeft = liveRect.left;
            const cTop = liveRect.top;

            for (let s = 0; s < count; s++) {
                const r = createdSpans[s].getBoundingClientRect();
                localX[s] = (r.left - cLeft) + r.width * 0.5;
                localY[s] = (r.top - cTop) + r.height * 0.5;
            }

            record = { spans: createdSpans, localX, localY, count };
            this.bakedContainers.set(container, record);
            return record;
        }

        _acquireEvent(timeMs, target, isContainer = false) {
            let ev = this._eventPool.pop();
            if (!ev) ev = { timeMs: 0, target: null, isContainer: false };
            ev.timeMs = timeMs;
            ev.target = target;
            ev.isContainer = isContainer;
            return ev;
        }

        prepareSegmentTimeline(segment) {
            // 回收旧事件回池
            for (let i = 0; i < this.currentTimeline.length; i++) {
                this._eventPool.push(this.currentTimeline[i]);
            }
            this.currentTimeline.length = 0;
            this.timelineIndex = 0;

            const p0x = segment.p0.x;
            const p0y = segment.p0.y;
            const p1x = segment.p1.x;
            const p1y = segment.p1.y;
            const dx = p1x - p0x;
            const dy = p1y - p0y;
            const lenSq = dx * dx + dy * dy;
            if (lenSq < 1) return;

            const segMinX = (p0x < p1x ? p0x : p1x) - BALL_RADIUS;
            const segMaxX = (p0x > p1x ? p0x : p1x) + BALL_RADIUS;
            const segMinY = (p0y < p1y ? p0y : p1y) - BALL_RADIUS;
            const segMaxY = (p0y > p1y ? p0y : p1y) + BALL_RADIUS;

            this._updateVisibleContainers();
            const vis = this.visibleContainers;
            const visLen = vis.length;
            if (visLen === 0) return;

            const invLenSq = 1 / lenSq;
            const dur = segment.durationMs;

            for (let i = 0; i < visLen; i++) {
                const item = vis[i];
                if (item.right < segMinX || item.left > segMaxX || item.bottom < segMinY || item.top > segMaxY) {
                    continue;
                }

                // 射线相交优化：优先读取已烘焙容器；若尚未烘焙，即时补足烘焙，确保文字 100% 参与字符级计算
                let baked = this.bakedContainers.get(item.el);
                if (!baked) {
                    baked = this.bakeContainer(item.el, item);
                    if (!baked) {
                        // 兜底容器级震动
                        const midX = (Math.max(item.left, segMinX) + Math.min(item.right, segMaxX)) * 0.5;
                        const midY = (Math.max(item.top, segMinY) + Math.min(item.bottom, segMaxY)) * 0.5;
                        const u = Math.max(0, Math.min(1, ((midX - p0x) * dx + (midY - p0y) * dy) * invLenSq));
                        this.currentTimeline.push(this._acquireEvent(u * dur, item.el, true));
                        continue;
                    }
                }

                const { spans, localX, localY, count } = baked;
                const baseLeft = item.left;
                const baseTop = item.top;

                // 局部 Y 轴范围剪裁（行剪裁）
                const localMinY = segMinY - baseTop;
                const localMaxY = segMaxY - baseTop;
                const localMinX = segMinX - baseLeft;
                const localMaxX = segMaxX - baseLeft;

                for (let k = 0; k < count; k++) {
                    const ly = localY[k];
                    if (ly < localMinY || ly > localMaxY) continue;
                    const lx = localX[k];
                    if (lx < localMinX || lx > localMaxX) continue;

                    const cx = baseLeft + lx;
                    const cy = baseTop + ly;

                    const u = ((cx - p0x) * dx + (cy - p0y) * dy) * invLenSq;
                    if (u < 0 || u > 1) continue;

                    const projX = p0x + u * dx - cx;
                    const projY = p0y + u * dy - cy;
                    if (projX * projX + projY * projY <= BALL_RADIUS_SQ) {
                        this.currentTimeline.push(this._acquireEvent(u * dur, spans[k], false));
                    }
                }
            }

            if (this.currentTimeline.length > 1) {
                this.currentTimeline.sort((a, b) => a.timeMs - b.timeMs);
            }
        }

        // 每帧推进时间轴并清理过期抖动
        updateTimeline(elapsedMs, now) {
            const tl = this.currentTimeline;
            const len = tl.length;
            while (this.timelineIndex < len && elapsedMs >= tl[this.timelineIndex].timeMs) {
                const ev = tl[this.timelineIndex++];
                const target = ev.target;
                if (!target) continue;

                if (ev.isContainer) {
                    if (!target.classList.contains('sl-mes-hit')) {
                        target.classList.add('sl-mes-hit');
                        this.activeShakes.push({ target, isContainer: true, endTime: now + 230 });
                    }
                } else {
                    if (!target.classList.contains('sl-shake')) {
                        target.classList.add('sl-shake');
                        this.activeShakes.push({ target, isContainer: false, endTime: now + 190 });
                    }
                }
            }

            // 批量回收
            for (let i = this.activeShakes.length - 1; i >= 0; i--) {
                const item = this.activeShakes[i];
                if (now >= item.endTime) {
                    if (item.isContainer) {
                        item.target.classList.remove('sl-mes-hit');
                    } else {
                        item.target.classList.remove('sl-shake');
                    }
                    const last = this.activeShakes.pop();
                    if (i < this.activeShakes.length) this.activeShakes[i] = last;
                }
            }
        }

        cleanup() {
            const s = this.doc.getElementById('__sl_shake_anim_style__');
            if (s) s.remove();
            for (const [container, originalHTML] of this.wrappedOriginals.entries()) {
                try { container.innerHTML = originalHTML; } catch (_) { }
            }
            this.wrappedOriginals.clear();
            this.bakedContainers.clear();
            this._idleBakeSet.clear();
            this._idleBakeQueue.length = 0;
            this._isIdleBaking = false;
            this.visibleContainers.length = 0;
            this.currentTimeline.length = 0;
            this.activeShakes.length = 0;
            this.timelineIndex = 0;
        }
    }

    // ==========================================
    // 7. 图标受击反馈系统 (Zero-Timer CSS Variable Driven)
    // ==========================================
    class IconImpactEngine {
        constructor(doc) {
            this.doc = doc;
            this.cachedTargets = [];
            this.activeHits = [];
            this.isDirty = true;
        }

        invalidate() {
            this.isDirty = true;
        }

        getTargetElements() {
            if (!this.isDirty) return this.cachedTargets;

            this.cachedTargets.length = 0;
            const list = this.doc.querySelectorAll(
                '#top-settings-holder .drawer-icon, #top-bar [role="button"], #top-settings-holder .menu_button, .avatar img, .mesAvatarWrapper img, #strategySelectors .toggle-item, .interactive-card'
            );

            for (let i = 0, len = list.length; i < len; i++) {
                const el = list[i];
                const r = el.getBoundingClientRect();
                if (r.width > 4 && r.height > 4) {
                    const isAvatar = el.tagName === 'IMG';
                    this.cachedTargets.push({
                        el,
                        type: isAvatar ? 'avatar' : 'icon',
                        rect: {
                            left: r.left,
                            top: r.top,
                            right: r.right,
                            bottom: r.bottom,
                            width: r.width,
                            height: r.height
                        }
                    });
                }
            }

            this.isDirty = false;
            return this.cachedTargets;
        }

        // 零 setTimeout：通过 CSS 变量注入冲量并交由 CSS Keyframes 完成回弹
        triggerIconImpactAnimation(el, nx, ny, type, now) {
            const pushAmp = type === 'avatar' ? 14 : 10;
            el.style.setProperty('--sl-px', `${(-nx * pushAmp).toFixed(1)}px`);
            el.style.setProperty('--sl-py', `${(-ny * pushAmp).toFixed(1)}px`);
            el.style.setProperty('--sl-rot', `${((Math.random() - 0.5) * 35).toFixed(1)}deg`);

            if (!el.classList.contains('sl-icon-hit')) {
                el.classList.add('sl-icon-hit');
                this.activeHits.push({ el, endTime: now + 490 });
            }
        }

        updateActiveHits(now) {
            for (let i = this.activeHits.length - 1; i >= 0; i--) {
                if (now >= this.activeHits[i].endTime) {
                    this.activeHits[i].el.classList.remove('sl-icon-hit');
                    const last = this.activeHits.pop();
                    if (i < this.activeHits.length) this.activeHits[i] = last;
                }
            }
        }
    }

    // ==========================================
    // 8. 游戏主调度控制器 (Dirty-Rect & On-Demand Loop)
    // ==========================================
    class SlingshotGameApp {
        constructor(win, doc) {
            this.win = win;
            this.doc = doc;
            this.showBoundsGuide = true;

            this.boundaryMgr = new SlingshotBoundaryManager(win, doc);
            this.planner = new TrajectoryPlanner(win, doc, this.boundaryMgr);
            this.particleMgr = new ParticleManager();
            this.slingshot = new SlingshotRenderer(win, doc, this.boundaryMgr);
            this.textEngine = new TextSweepEngine(win, doc, this.boundaryMgr);
            this.iconEngine = new IconImpactEngine(doc);

            this.guideCanvas = null;
            this.guideCtx = null;
            this.guideDirty = true;
            this.initGuideCanvas();

            // 脏矩形追踪（当关闭框线引导时启用局部擦除）
            this.dirtyBox = { x: 0, y: 0, w: 0, h: 0, valid: false };

            this.slingshot.onWake = () => this.wakeLoop();
            this.slingshot.onDragStart = () => {
                this.boundaryMgr.update(true);
                this.textEngine.invalidateCache();
                this.textEngine._updateVisibleContainers();
                const vis = this.textEngine.visibleContainers;
                for (let i = 0, len = vis.length; i < len; i++) {
                    this.textEngine.requestIdleBake(vis[i].el, vis[i]);
                }
            };
            this.slingshot.onRequestRender = () => this.requestSingleRender();
            this.slingshot.onInvalidateTargets = () => {
                this.iconEngine.invalidate();
                this.textEngine.invalidateCache();
                this.guideDirty = true;
            };

            this.activeSegments = [];
            this.segmentIndex = 0;
            this.currentSegment = null;
            this.segmentStartTime = 0;

            this.animFrameId = null;
            this.isRunning = true;
            this.toolbarEl = null;
            this._chatObserver = null;

            this.createFloatingToolbar();
            this.initMutationObserver();
            this.startLoop();
        }

        initMutationObserver() {
            if (typeof MutationObserver === 'undefined') return;
            const targetNode = this.boundaryMgr.chatEl || this.doc.getElementById('chat') || this.doc.getElementById('sheld') || this.doc.body;
            if (!targetNode) return;

            let mutRaf = null;
            this._chatObserver = new MutationObserver((mutations) => {
                // 性能过滤：如果是弹弓内部产生的 span 或 shake 样式，直接忽略，避免死循环
                let hasExternalChange = false;
                for (let i = 0, len = mutations.length; i < len; i++) {
                    const m = mutations[i];
                    if (m.type === 'childList') {
                        const added = m.addedNodes;
                        for (let a = 0, aLen = added.length; a < aLen; a++) {
                            const node = added[a];
                            if (node.nodeType === 1 && !node.classList.contains('sl-char') && node.id !== '__slingshot_canvas__' && node.id !== '__slingshot_control_bar__') {
                                hasExternalChange = true;
                                break;
                            }
                        }
                        if (hasExternalChange) break;
                    } else if (m.type === 'characterData') {
                        const parent = m.target.parentElement;
                        if (!parent || !parent.classList.contains('sl-char')) {
                            hasExternalChange = true;
                            break;
                        }
                    }
                }

                if (!hasExternalChange) return;

                if (mutRaf) return;
                mutRaf = this.win.requestAnimationFrame(() => {
                    mutRaf = null;
                    this.boundaryMgr.markDirty();
                    this.iconEngine.invalidate();
                    this.textEngine.invalidateCache();
                    this.guideDirty = true;
                    if (this.slingshot && this.slingshot.state === 'IDLE') {
                        this.boundaryMgr.update();
                        this.slingshot.updateSlingGeometry();
                        this.slingshot.resetBallToSling();
                        if (this.requestSingleRender) this.requestSingleRender();
                    }
                });
            });

            try {
                this._chatObserver.observe(targetNode, {
                    childList: true,
                    subtree: true,
                    characterData: true
                });
            } catch (_) { }
        }

        initGuideCanvas() {
            this.guideCanvas = this.doc.createElement('canvas');
            this.guideCtx = this.guideCanvas.getContext('2d');
            this.guideDirty = true;
        }

        advanceToNextSegment(now) {
            if (this.segmentIndex >= this.activeSegments.length) {
                const startPos = this.currentSegment ? this.currentSegment.p1 : this.slingshot.ball;
                let vx = this.currentSegment ? this.currentSegment.nextVel.x : this.slingshot.ball.vx;
                let vy = this.currentSegment ? this.currentSegment.nextVel.y : this.slingshot.ball.vy;

                const sp = Math.hypot(vx, vy) || 16;
                const targetSp = Math.max(14, Math.min(26, sp));
                const scale = targetSp / sp;
                vx *= scale;
                vy *= scale;

                const iconTargets = this.iconEngine.getTargetElements();
                const lastTarget = this.currentSegment && this.currentSegment.hitType === 'icon' ? this.currentSegment.hitTarget : null;
                const lastNormX = this.currentSegment ? this.currentSegment.normal.x : 0;
                const lastNormY = this.currentSegment ? this.currentSegment.normal.y : 0;
                this.activeSegments = this.planner.planSegments(startPos, vx, vy, 4, iconTargets, lastTarget, lastNormX, lastNormY);
                this.segmentIndex = 0;
            }

            if (this.currentSegment) {
                this.segmentStartTime += this.currentSegment.durationMs;
                // 限制最大延迟时间差不超过 100ms，杜绝切屏或主线程卡顿导致下一段被无脑穿透
                if (now - this.segmentStartTime > 100) {
                    this.segmentStartTime = now;
                }
            } else {
                this.segmentStartTime = now;
            }

            this.currentSegment = this.activeSegments[this.segmentIndex++];
            if (this.currentSegment) {
                this.textEngine.prepareSegmentTimeline(this.currentSegment);
            }
        }

        renderGuideOffscreen() {
            if (!this.guideCanvas || !this.guideCtx) return;
            const canvas = this.slingshot.canvas;
            if (!canvas) return;

            const w = canvas.width;
            const h = canvas.height;
            if (this.guideCanvas.width !== w || this.guideCanvas.height !== h) {
                this.guideCanvas.width = w;
                this.guideCanvas.height = h;
            }

            const gCtx = this.guideCtx;
            gCtx.setTransform(1, 0, 0, 1, 0, 0);
            gCtx.clearRect(0, 0, w, h);
            if (!this.showBoundsGuide) {
                this.guideDirty = false;
                return;
            }

            const dpr = this.slingshot.dpr || 1;
            gCtx.setTransform(dpr, 0, 0, dpr, 0, 0);

            const b = this.boundaryMgr.bounds;
            gCtx.strokeStyle = 'rgba(255, 59, 48, 0.55)';
            gCtx.lineWidth = 2.5;
            gCtx.setLineDash([8, 6]);

            const r = 12;
            gCtx.beginPath();
            gCtx.moveTo(b.left + r, b.top);
            gCtx.lineTo(b.right - r, b.top);
            gCtx.quadraticCurveTo(b.right, b.top, b.right, b.top + r);
            gCtx.lineTo(b.right, b.bottom - r);
            gCtx.quadraticCurveTo(b.right, b.bottom, b.right - r, b.bottom);
            gCtx.lineTo(b.left + r, b.bottom);
            gCtx.quadraticCurveTo(b.left, b.bottom, b.left, b.bottom - r);
            gCtx.lineTo(b.left, b.top + r);
            gCtx.quadraticCurveTo(b.left, b.top, b.left + r, b.top);
            gCtx.closePath();
            gCtx.stroke();

            const anchor = this.boundaryMgr.anchor;
            gCtx.strokeStyle = 'rgba(76, 217, 100, 0.85)';
            gCtx.lineWidth = 3;
            gCtx.setLineDash([]);
            gCtx.beginPath();
            gCtx.moveTo(b.left + 10, anchor.y);
            gCtx.lineTo(b.right - 10, anchor.y);
            gCtx.stroke();

            this.guideDirty = false;
        }

        drawBoundingBoxGuide(ctx) {
            if (!this.showBoundsGuide) return;
            if (this.guideDirty) this.renderGuideOffscreen();
            if (this.guideCanvas) {
                const dpr = this.slingshot.dpr || 1;
                ctx.setTransform(1, 0, 0, 1, 0, 0);
                ctx.drawImage(this.guideCanvas, 0, 0);
                ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
            }
        }

        startLoop() {
            const self = this;

            function renderFrame(now) {
                const ctx = self.slingshot.ctx;
                const canvas = self.slingshot.canvas;
                if (!ctx || !canvas) return;

                // 擦除策略：开启框线时全屏擦除并贴离屏图；关闭框线时仅擦除上一帧脏矩形包围盒
                if (self.showBoundsGuide || !self.dirtyBox.valid) {
                    ctx.clearRect(0, 0, self.slingshot.logicalWidth, self.slingshot.logicalHeight);
                } else {
                    const db = self.dirtyBox;
                    ctx.clearRect(db.x, db.y, db.w, db.h);
                }

                self.drawBoundingBoxGuide(ctx);

                if (self.slingshot.state === 'FLYING') {
                    if (!self.currentSegment) {
                        self.advanceToNextSegment(now);
                    }

                    const seg = self.currentSegment;
                    if (seg) {
                        const elapsed = Math.max(0, now - self.segmentStartTime);
                        const progress = Math.min(1, elapsed / seg.durationMs);

                        const ball = self.slingshot.ball;
                        ball.x = seg.p0.x + (seg.p1.x - seg.p0.x) * progress;
                        ball.y = seg.p0.y + (seg.p1.y - seg.p0.y) * progress;

                        self.textEngine.updateTimeline(elapsed, now);

                        if (progress >= 1) {
                            if (seg.hitType === 'icon' && seg.hitTarget) {
                                self.iconEngine.triggerIconImpactAnimation(seg.hitTarget.el, seg.normal.x, seg.normal.y, seg.hitTarget.type, now);
                                const sparkColor = seg.hitTarget.type === 'avatar' ? '#ff4081' : '#00e5ff';
                                self.particleMgr.emitSparks(seg.p1.x, seg.p1.y, seg.normal.x, seg.normal.y, 4, sparkColor);
                            } else {
                                self.particleMgr.emitSparks(seg.p1.x, seg.p1.y, seg.normal.x, seg.normal.y, 2, '#ff5252');
                            }

                            self.advanceToNextSegment(now);

                            const nextSeg = self.currentSegment;
                            if (nextSeg) {
                                const nextElapsed = Math.max(0, Math.min(nextSeg.durationMs * 0.4, now - self.segmentStartTime));
                                const nextProgress = Math.min(1, nextElapsed / nextSeg.durationMs);
                                ball.x = nextSeg.p0.x + (nextSeg.p1.x - nextSeg.p0.x) * nextProgress;
                                ball.y = nextSeg.p0.y + (nextSeg.p1.y - nextSeg.p0.y) * nextProgress;
                            }
                        }
                    }
                } else if (self.textEngine.activeShakes.length > 0) {
                    self.textEngine.updateTimeline(0, now);
                }

                if (self.iconEngine.activeHits.length > 0) {
                    self.iconEngine.updateActiveHits(now);
                }

                self.slingshot.drawSlingshot(ctx);
                self.slingshot.drawBall(ctx);
                self.particleMgr.updateAndDraw(ctx);

                // 计算本帧动态元素脏矩形包围盒供下一帧局部擦除
                if (!self.showBoundsGuide) {
                    const bx = self.slingshot.ball.x;
                    const by = self.slingshot.ball.y;
                    const fx = self.slingshot.forkBase.x;
                    const fy = self.slingshot.forkBase.y;

                    let minX = Math.min(bx - 25, fx - 140);
                    let maxX = Math.max(bx + 25, fx + 140);
                    let minY = Math.min(by - 25, fy - 160);
                    let maxY = Math.max(by + 25, fy + 40);

                    const pts = self.particleMgr.particles;
                    for (let i = 0, len = pts.length; i < len; i++) {
                        const p = pts[i];
                        if (p.x - 10 < minX) minX = p.x - 10;
                        if (p.x + 10 > maxX) maxX = p.x + 10;
                        if (p.y - 10 < minY) minY = p.y - 10;
                        if (p.y + 10 > maxY) maxY = p.y + 10;
                    }

                    self.dirtyBox.x = Math.max(0, Math.floor(minX));
                    self.dirtyBox.y = Math.max(0, Math.floor(minY));
                    self.dirtyBox.w = Math.ceil(maxX - self.dirtyBox.x);
                    self.dirtyBox.h = Math.ceil(maxY - self.dirtyBox.y);
                    self.dirtyBox.valid = true;
                } else {
                    self.dirtyBox.valid = false;
                }
            }

            function loop(now) {
                if (!self.isRunning) return;

                renderFrame(now);

                const active = self.slingshot.state === 'FLYING' ||
                    self.slingshot.state === 'DRAGGING' ||
                    self.particleMgr.particles.length > 0 ||
                    self.textEngine.activeShakes.length > 0 ||
                    self.iconEngine.activeHits.length > 0;

                if (active) {
                    self.animFrameId = self.win.requestAnimationFrame(loop);
                } else {
                    self.animFrameId = null;
                }
            }

            this.wakeLoop = function () {
                if (!self.animFrameId && self.isRunning) {
                    self.animFrameId = self.win.requestAnimationFrame(loop);
                }
            };

            this.requestSingleRender = function () {
                self.dirtyBox.valid = false;
                self.win.requestAnimationFrame(renderFrame);
            };

            this.requestSingleRender();
        }

        recallBall() {
            this.currentSegment = null;
            this.activeSegments.length = 0;
            this.segmentIndex = 0;
            this.slingshot.resetBallToSling();
            this.textEngine.cleanup();
            this.textEngine.injectStyles();
            if (this.requestSingleRender) this.requestSingleRender();
        }

        createFloatingToolbar() {
            const bar = this.doc.createElement('div');
            bar.id = '__slingshot_control_bar__';
            bar.style.cssText = 'position:fixed;right:18px;bottom:85px;z-index:999999;display:flex;align-items:center;gap:8px;padding:6px 12px;background:rgba(28,28,30,0.88);border:1px solid rgba(255,255,255,0.15);border-radius:24px;box-shadow:0 8px 24px rgba(0,0,0,0.4);user-select:none;font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,sans-serif;font-size:12px;color:#fff;';

            const recallBtn = this.doc.createElement('button');
            recallBtn.textContent = '🎯 召回小球';
            recallBtn.style.cssText = 'background:linear-gradient(135deg,#ff5252,#d50000);border:none;color:#fff;padding:5px 12px;border-radius:16px;cursor:pointer;font-weight:bold;box-shadow:0 2px 8px rgba(255,82,82,0.4);';
            recallBtn.onclick = () => this.recallBall();

            const boundsBtn = this.doc.createElement('button');
            boundsBtn.textContent = '🔲 框线';
            boundsBtn.style.cssText = 'background:rgba(76,217,100,0.4);border:none;color:#fff;padding:5px 10px;border-radius:16px;cursor:pointer;';
            boundsBtn.onclick = () => {
                this.showBoundsGuide = !this.showBoundsGuide;
                this.guideDirty = true;
                this.dirtyBox.valid = false;
                boundsBtn.style.background = this.showBoundsGuide ? 'rgba(76,217,100,0.4)' : 'rgba(255,255,255,0.12)';
                if (this.requestSingleRender) this.requestSingleRender();
            };

            const closeBtn = this.doc.createElement('button');
            closeBtn.textContent = '✕';
            closeBtn.style.cssText = 'background:transparent;border:none;color:rgba(255,255,255,0.6);padding:4px 6px;cursor:pointer;font-size:14px;';
            closeBtn.onclick = () => this.destroy();

            bar.appendChild(recallBtn);
            bar.appendChild(boundsBtn);
            bar.appendChild(closeBtn);

            this.doc.body.appendChild(bar);
            this.toolbarEl = bar;
        }

        destroy() {
            this.isRunning = false;
            if (this.animFrameId) {
                this.win.cancelAnimationFrame(this.animFrameId);
                this.animFrameId = null;
            }
            if (this.slingshot) {
                this.slingshot.destroy();
                this.slingshot = null;
            }
            if (this.toolbarEl) {
                this.toolbarEl.remove();
                this.toolbarEl = null;
            }
            if (this._chatObserver) {
                this._chatObserver.disconnect();
                this._chatObserver = null;
            }
            if (this.textEngine) {
                this.textEngine.cleanup();
            }
            this.guideCanvas = null;
            this.guideCtx = null;
        }
    }

    const gameInstance = new SlingshotGameApp(hostWin, hostDoc);
    hostWin[GAME_INSTANCE_KEY] = gameInstance;
    global.slingshotGame = gameInstance;

})(typeof window !== 'undefined' ? window : this);
